#!/usr/bin/env python3
# PT_ADDPERSON_V2 — rebuilt Add-person flow: Who / Reports-to / optional Team (with New team + make-lead
# as a tag). Decouples reporting (managerMid) from team (functionId); fixes forced-department and duplicate
# bugs. Replaces modal DOM, openPerson, the ps helper block, and savePerson. Idempotent.
import sys, base64
SENT='id="ps-rep"'
PAIRS=[('', ''), ('', ''), ('', ''), ('', '')]
def d64(s): return base64.b64decode(s).decode("utf-8")
def main():
    if len(sys.argv)<2: sys.exit("usage: python3 build_addperson_v2_patch.py index.html")
    p=sys.argv[1]; d=open(p,encoding="utf-8").read()
    if SENT in d: print("PT_ADDPERSON_V2 already present — no-op."); return
    for i,(eo,en) in enumerate(PAIRS):
        o=d64(eo); n=d64(en); c=d.count(o)
        if c!=1: sys.exit("ABORT: region %d count %d (expected 1)"%(i,c))
        d=d.replace(o,n,1)
    open(p,"w",encoding="utf-8").write(d); print("PT_ADDPERSON_V2 applied OK (4 regions).")
main()
